// ---- dual theme ------------------------------------------------------------
// Every palette binding is a plain `let` and every widget mints inside fns
// that repaint() re-runs, so identifiers resolve at RE-MINT time. Switching
// the theme is just reassigning the bindings and repainting the three
// persistent roots (sidebar, chrome, body).
//
// themeMode: "system" follows the host's light/dark (read from the palette
// the shell retints us with — mod.theme.color_bg_app is light when the
// system is light), "light" / "dark" pin it manually. The choice persists
// to theme.json in the app's storage; the boot poller re-checks the system
// appearance so a Shell toggle re-themes a running app within ~1s.
let themeLight = true        // boot in the warm-paper light theme
let themeMode = "system"     // system | light | dark

fn save_theme_mode(){
    fs.write("theme.json", "{\"mode\":\"" + themeMode + "\"}")
}
fn load_theme_mode(){
    if fs.exists("theme.json") {
        let v = fs.read("theme.json").parse_json()
        if v != nil {
            if v.mode == "light" { themeMode = "light" return }
            if v.mode == "dark" { themeMode = "dark" return }
            themeMode = "system"
        }
    }
}
// The host palette's app background: light when the system is light, dark
// when it is dark (the shell retints this when its appearance changes).
// Only the shell's two exact palette values count as "the system theme" —
// a stock card-host has no sheet, and its built-in dark must read as
// "cannot tell" (nil) so the app falls back to the light default instead
// of following a theme the person never chose.
fn system_prefers_dark(){
    let bg = mod.theme.color_bg_app
    if bg == nil { return nil }
    if bg == #xeff5f6 { return false }
    if bg == #x0b1220 { return true }
    return nil
}
// Resolve to "is light": manual modes pin it; system mode inverts the
