// ---- helpers --------------------------------------------------------------
fn pick(c, a, b){ if c { return a } return b }
fn first_line(s){ let ls = s.split("\n") return ls[0] }
fn domain_of(a){
    let parts = a.split("@")
    if parts.len() > 1 { return parts[1] }
    return a
}
// tone -> chip colors (label chips everywhere read these)
fn chip_fg(tone){
    if tone == "violet" { return violetT }
    if tone == "cyan" { return cyanT }
    if tone == "amber" { return amberT }
    if tone == "red" { return redT }
    return mintT
}
fn chip_bg(tone){
    if tone == "violet" { return violetBg }
    if tone == "cyan" { return cyanBg }
    if tone == "amber" { return amberBg }
    if tone == "red" { return redBg }
    return mintBg
}
fn chip_ln(tone){
    if tone == "violet" { return violetBd }
    if tone == "cyan" { return cyanBd }
    if tone == "amber" { return amberBd }
    if tone == "red" { return redBd }
    return mintBd
}
// priority -> score color (>=85 red, >=65 amber, >=45 cyan, else violet-2)
fn pri_color(p){
    if p >= 85 { return red }
    if p >= 65 { return amber }
    if p >= 45 { return cyan }
    return violet2
}
fn pri_w(p){
    if p >= 95 { return 34 }
    if p >= 85 { return 31 }
    if p >= 65 { return 24 }
    if p >= 45 { return 17 }
    if p >= 25 { return 10 }
    return 5
}
fn has_label(m, t){
    for l in m.labels { if l.text == t { return true } }
    return false
}
fn pass_filter(i){
    if filter == "urgent" { return mails[i].priority >= 85 }
    if filter == "reply" { return has_label(mails[i], "需回复") }
    if filter == "later" { return is_later(i) }
    return true
}
fn is_later(i){
    if mails[i].priority >= 85 { return false }
    if has_label(mails[i], "需回复") { return false }
    return true
}
// sidebar scope: which mails the list column currently offers. The 邮箱
// folders and AI 智能分类 rows are real filters over the same dataset.
fn pass_scope(i){
    let m = mails[i]
    if cluster_sel != "" { return m.cluster == cluster_sel && m.boxed == "" }
    if folder == "starred" { return m.star && m.boxed == "" }
    if folder == "later" { return is_later(i) && m.boxed == "" }
    if folder == "sent" { return m.reply == "sent" && m.boxed == "" }
    if folder == "drafts" { return m.reply_text != "" && m.reply != "sent" && m.boxed == "" }
    if folder == "archive" { return m.boxed == "archive" }
    if folder == "trash" { return m.boxed == "trash" }
    return m.boxed == ""
}
// filter-chip counts are SCOPE-aware; the triage banner keeps the global tally
fn cnt(kind){
    let n = 0
    for i in mails.len() {
        if mails[i].boxed == "" {
            if kind == "all" { n = n + 1 }
            if kind == "urgent" { if mails[i].priority >= 85 { n = n + 1 } }
            if kind == "reply" { if has_label(mails[i], "需回复") { n = n + 1 } }
            if kind == "later" { if is_later(i) { n = n + 1 } }
        }
    }
    return n
}
fn cnt_chip(kind){
    let n = 0
    for i in mails.len() {
        if pass_scope(i) {
            if kind == "all" { n = n + 1 }
            if kind == "urgent" { if mails[i].priority >= 85 { n = n + 1 } }
            if kind == "reply" { if has_label(mails[i], "需回复") { n = n + 1 } }
            if kind == "later" { if is_later(i) { n = n + 1 } }
        }
    }
    return n
}
fn cnt_vis(){
    let n = 0
    for i in mails.len() {
        if pass_scope(i) { if pass_filter(i) { n = n + 1 } }
    }
    return n
}
// sidebar folder badges — live counts, blank when zero
fn cntf(kind){
    let n = 0
    for i in mails.len() {
        let m = mails[i]
        if kind == "starred" { if m.star && m.boxed == "" { n = n + 1 } }
        if kind == "later" { if is_later(i) && m.boxed == "" { n = n + 1 } }
        if kind == "sent" { if m.reply == "sent" && m.boxed == "" { n = n + 1 } }
        if kind == "drafts" { if m.reply_text != "" && m.reply != "sent" && m.boxed == "" { n = n + 1 } }
        if kind == "archive" { if m.boxed == "archive" { n = n + 1 } }
