// ---- navigation -----------------------------------------------------------
// ui is injected only after the body evaluates, so the first frame draws an
// empty body; a boot timeout re-renders it once ui exists (README pattern).
let want_list = false          // sync done -> the poller should fetch the list
let mail_poll = nil
let sys_checks = 0             // system-appearance checks between theme reads
fn poll_step(){
    // All mail requests are issued from THIS top-level interval (or user
    // gestures): timers registered inside a host-reply callback are dropped
    // by the shell's runner, so replies only ever set flags. In system mode
    // the same poller samples the host palette every ~2s and follows a
    // light/dark switch of the Shell without restarting the app.
    if want_list {
        want_list = false
        mail_list()
    }
    sys_checks = sys_checks + 1
    if themeMode == "system" {
        if sys_checks >= 5 {
            sys_checks = 0
            let want_light = resolve_theme()
            if want_light != themeLight {
                apply_theme(want_light)
                repaint()
            }
        }
    }
}
fn boot(){
    load_theme_mode()
    apply_theme(resolve_theme())
    repaint()
    mail_check()
    mail_poll = start_interval(0.4, || poll_step())
}
start_timeout(0.05, || boot())

