// ---- shared bits (warm-paper x forest-ink redesign) -------------------------
// Reference: UI设计-新/app (Sidebar/Chrome/InboxList/ReadingPane/ComposeView/
// AgentsView/bits). Native widgets only. All iconography is DRAWN — see the
// drawn icon family above (runtime SVG rasterises blank here, and font
// dingbats rendered at the mercy of CJK fallbacks until 0.6.16).
// Palette var names are historical (violet:=accent forest green, cyan:=teal,
// mint:=ok green) — the values rebind per theme in apply_theme.

fn chip(text, tone){
    RoundedView{width: Fit height: Fit padding: Inset{top: 2 bottom: 2 left: 6 right: 6}
        draw_bg +: {color: chip_bg(tone) border_radius: 6.0 border_size: 1.0 border_color: chip_ln(tone)}
        Label{text: text draw_text.color: chip_fg(tone) draw_text.text_style.font_size: 10}}
}
fn label_row(m){
    View{width: Fill height: Fit flow: Right spacing: 5
        for l in m.labels { chip(l.text, l.tone) }
    }
}
// AI priority meter: fixed footprint — the row's right edge anchor
fn priority_meter(m){
    View{width: 48 height: Fit flow: Right spacing: 4 align: Align{y: 0.5}
        RoundedView{width: 26 height: 3 draw_bg +: {color: white7 border_radius: 2.0} flow: Overlay
            RoundedView{width: pri_w(m.priority) height: 3 draw_bg +: {color: pri_color(m.priority) border_radius: 2.0}}
        }
        Label{text: "" + m.priority draw_text.color: pri_color(m.priority) draw_text.text_style.font_size: 9}
    }
}
// Gradient avatar — the practice dataset carries a two-tone pair per sender.
// Live mails arrive without initials: the avatar draws the envelope glyph.
fn avatar(i, size, unread){
    RoundedView{width: size height: size draw_bg +: {color: mails[i].av1 border_radius: size / 2.0} flow: Overlay align: Align{x: 0.5 y: 0.5}
        if mails[i].init == "✉" {
