// nav rows carry an ICON KEY minted through ui_icon — no font glyphs anywhere
fn nav_row(icon_key, label, target, badge){
    let act = screen == target
    GestureView{width: Fill height: 36 on_tap: |x, y| go(target)
        RoundedView{width: Fill height: 36
            draw_bg +: {color: pick(act, violetBg, #x00000000) border_radius: 9.0 border_size: 1.0 border_color: pick(act, violetBd, #x00000000)}
            View{width: Fill height: Fill flow: Right spacing: 10 align: Align{y: 0.5} padding: Inset{left: 10 right: 10}
                View{width: 16 height: 16 align: Align{x: 0.5 y: 0.5}
                    ui_icon(icon_key, pick(act, violetT, ink45), 14, pick(act, violetBg, panel))}
                Label{width: Fill text: label draw_text.color: pick(act, ink, ink66) draw_text.text_style.font_size: 13}
                if badge != "" {
                    RoundedView{width: Fit height: Fit padding: Inset{top: 1 bottom: 1 left: 7 right: 7}
                        draw_bg +: {color: pick(act, violet, violetBg) border_radius: 9.0}
                        Label{text: badge draw_text.color: pick(act, accInk, violetT) draw_text.text_style.font_size: 10}}
                }
            }
        }
    }
}
