// folder rows are real filters: tap scopes the list, tap again to leave
fn folder_row(icon_key, label, count, key){
    let act = folder == key && cluster_sel == ""
    GestureView{width: Fill height: 36 on_tap: |x, y| set_folder(key)
        RoundedView{width: Fill height: 36
            draw_bg +: {color: pick(act, violetBg, #x00000000) border_radius: 9.0 border_size: 1.0 border_color: pick(act, violetBd, #x00000000)}
            View{width: Fill height: Fill flow: Right spacing: 10 align: Align{y: 0.5} padding: Inset{left: 10 right: 10}
                View{width: 16 height: 16 align: Align{x: 0.5 y: 0.5}
                    ui_icon(icon_key, pick(act, violetT, ink45), 14, pick(act, violetBg, panel))}
                Label{width: Fill text: label draw_text.color: pick(act, ink, ink66) draw_text.text_style.font_size: 12.5}
                if count != "" {
                    Label{text: count draw_text.color: pick(act, violetT, ink45) draw_text.text_style.font_size: 10}
                }
            }
        }
    }
}
fn cluster_color(k){
    if k == "teal" { return cyan }
    if k == "ok" { return mint }
    if k == "amber" { return amber }
    return violet
}
fn cluster_row(label, count, key){
    let act = cluster_sel == label
    GestureView{width: Fill height: 36 on_tap: |x, y| set_cluster(label)
        RoundedView{width: Fill height: 36
            draw_bg +: {color: pick(act, violetBg, #x00000000) border_radius: 9.0 border_size: 1.0 border_color: pick(act, violetBd, #x00000000)}
            View{width: Fill height: Fill flow: Right spacing: 10 align: Align{y: 0.5} padding: Inset{left: 10 right: 10}
                RoundedView{width: 7 height: 7 draw_bg +: {color: cluster_color(key) border_radius: 4.0}}
                Label{width: Fill text: label draw_text.color: pick(act, ink, ink66) draw_text.text_style.font_size: 12.5}
                Label{text: count draw_text.color: pick(act, violetT, ink45) draw_text.text_style.font_size: 10}
            }
        }
    }
}
