            View{width: Fit height: Fit flow: Down spacing: 3
                Label{text: "VibeMail" draw_text.color: ink draw_text.text_style: theme.font_bold{font_size: 15}}
                Label{text: "AGENTIC MAIL" draw_text.color: ink45 draw_text.text_style.font_size: 8.5}}
        }
        RoundedView{width: Fill height: 1 draw_bg +: {color: sepC border_radius: 0.0}}
        ScrollYView{width: Fill height: Fill flow: Down padding: Inset{top: 14 bottom: 10 left: 12 right: 12}
            // 写信 · AI 起草 — the accent gradient CTA
            GestureView{width: Fill height: 40 on_tap: |x, y| go("write")
                RoundedView{width: Fill height: 40 draw_bg +: {color: violet border_radius: 10.0}
                    View{width: Fill height: 40 flow: Right spacing: 8 align: Align{y: 0.5} padding: Inset{left: 12 right: 8}
                        View{width: 16 height: 16 align: Align{x: 0.5 y: 0.5}
                            spark_icon(accInk, 15)}
                        Label{width: Fill text: "写信 · AI 起草" draw_text.color: accInk draw_text.text_style: theme.font_bold{font_size: 12.5}}
                        kbd_on_acc("Ctrl N")
                    }
