            }
            // main nav
            View{width: 1 height: 12}
            nav_row("mail", "收件箱", "inbox", "" + cnt("all"))
            agents_nav_row("Agent 小队", "agents", "" + agents.len())
            // mailbox folders — real scopes, live badge counts
            View{width: 1 height: 24}
            section_label("邮箱")
            folder_row("star", "已加星标", show_cnt(cntf("starred")), "starred")
            folder_row("clock", "稍后处理", show_cnt(cntf("later")), "later")
