                    spark_icon(violetT, 9.5)}}
            cluster_row("工作", show_cnt(cnt_cluster("工作")), "acc")
            cluster_row("财务", show_cnt(cnt_cluster("财务")), "teal")
            cluster_row("订阅", show_cnt(cnt_cluster("订阅")), "ok")
            cluster_row("社交", show_cnt(cnt_cluster("社交")), "amber")
        }
        // agent mini card — AGENT ACTIVE + today's practice tally
        View{width: Fill height: Fit padding: Inset{left: 12 right: 12 bottom: 12}
            RoundedView{width: Fill height: Fit padding: Inset{top: 14 bottom: 14 left: 16 right: 16}
                draw_bg +: {color: panel2 border_radius: 12.0 border_size: 1.0 border_color: line} flow: Down spacing: 8
