                Label{width: Fill text: "今日已自动处理 23 封邮件,节省 1.4h" draw_text.color: ink66 draw_text.text_style.font_size: 11}
                RoundedView{width: Fill height: 3 draw_bg +: {color: line border_radius: 2.0} flow: Overlay
                    RoundedView{width: 141 height: 3 draw_bg +: {color: violet border_radius: 2.0}}}
            }
        }
        // footer: calendar / settings + account avatar
        RoundedView{width: Fill height: 1 draw_bg +: {color: sepC border_radius: 0.0}}
        View{width: Fill height: 52 flow: Right spacing: 2 align: Align{y: 0.5} padding: Inset{left: 10 right: 12}
