fn title_zh(){
    if screen == "write" { return "AI 写信" }
    if screen == "agents" { return "Agent 小队" }
    return "智能收件箱"
}
fn top_bar(){
    // Narrow-proof chrome: no EN subtitle and no kbd badge — the fixed run
    // (title 14 + search 230 + compact pill + toggle + bell) is ~640 logical
    // px so even a hi-DPI shell's ~660px column keeps every element on screen
    // (probed: at a 940px window nothing crosses the right edge).
    RoundedView{width: Fill height: 60 flow: Right spacing: 8 align: Align{y: 0.5} padding: Inset{left: 16 right: 12} draw_bg +: {color: glass border_radius: 0.0}
        Label{text: title_zh() draw_text.color: ink draw_text.text_style: theme.font_bold{font_size: 14}}
        View{width: Fill height: 1}
        // agent search — ask Vibe Agent anything (⌘K in the reference)
        RoundedView{width: 230 height: 36 draw_bg +: {color: panel border_radius: 10.0 border_size: 1.0 border_color: line}
            View{width: Fill height: Fill flow: Right spacing: 8 align: Align{y: 0.5} padding: Inset{left: 12 right: 12}
                View{width: 14 height: 14 align: Align{x: 0.5 y: 0.5}
                    spark_icon(ink45, 12)}
                Label{width: Fill text: "问 Vibe Agent:查邮件" draw_text.color: ink55 draw_text.text_style.font_size: 12}
            }
        }
        View{width: Fill height: 1}
        agent_pill()
        theme_toggle()
        // notifications — real panel: approvals / failures / drafts / urgent;
        // the red dot only shows while something needs an action
        GestureView{width: 36 height: 36 on_tap: |x, y| open_pop("bell")
            View{width: 36 height: 36 flow: Overlay
                RoundedView{width: 36 height: 36 draw_bg +: {color: #x00000000 border_radius: 10.0 border_size: 1.0 border_color: line} align: Align{x: 0.5 y: 0.5}
                    bell_icon(ink55, 15)}
                if notify_cnt() > 0 {
                    View{width: Fill height: Fill align: Align{x: 1.0 y: 0.0}
                        View{width: 14 height: 14 align: Align{x: 0.5 y: 0.5}
                            RoundedView{width: 6 height: 6 draw_bg +: {color: red border_radius: 3.0}}}
                    }
                }
            }
        }
    }
}

// ---- inbox: list | reading (inline AI brief) -------------------------------
fn banner_line(){
    if mail_link == "checking" { return "正在连接邮件服务…" }
    if mail_link == "live" { return "已连接 " + account_addr + " · " + live_total + " 封真实邮件" }
    if mail_link == "no_account" { return "未添加邮箱账号 · 在左下角「设置」里添加" }
    if mail_link == "error" { return "邮箱连接失败:" + link_error }
    return "邮件服务不可用 · 当前为练习数据"
}
fn filter_chip(key, label, count){
    ButtonFlat{height: 32 padding: Inset{left: 11 right: 11} text: label + " " + count on_click: || set_filter(key)
        draw_bg +: {color: pick(filter == key, violetBg, #x00000000) color_hover: white7 color_down: white7
                    border_radius: 8.0 border_size: 1.0 border_color: pick(filter == key, violetBd, line2)}
        draw_text +: {color: pick(filter == key, violetT, ink66) text_style.font_size: 12}}
}
fn mail_row(i){
    let m = mails[i]
    let sel = selected && i == current
    GestureView{width: Fill height: Fit on_tap: |x, y| open_mail(i)
        View{width: Fill height: Fit flow: Overlay
            RoundedView{width: Fill height: Fit flow: Down padding: Inset{top: 14 bottom: 14 left: 20 right: 20} spacing: 5
                draw_bg +: {color: pick(sel, violetBg, #x00000000) border_radius: 0.0}
                View{width: Fill height: Fit flow: Right spacing: 11
                    avatar(i, 38, m.unread)
                    View{width: Fill height: Fit flow: Down spacing: 5
                        View{width: Fill height: Fit flow: Right spacing: 8 align: Align{y: 0.5}
                            if m.unread {
                                Label{width: Fill text: m.sender draw_text.color: ink draw_text.text_style: theme.font_bold{font_size: 13}}
                            } else {
                                Label{width: Fill text: m.sender draw_text.color: ink66 draw_text.text_style.font_size: 12.5}
                            }
                            Label{width: 44 text: m.time draw_text.color: ink45 draw_text.text_style.font_size: 10}
                        }
                        Label{width: Fill text: m.subject draw_text.color: pick(m.unread, inkHi, ink66) draw_text.text_style.font_size: 12.5}
                        Label{width: Fill text: m.snippet draw_text.color: ink45 draw_text.text_style.font_size: 11}
                        View{width: Fill height: Fit flow: Right spacing: 5 align: Align{y: 0.5}
                            if m.generating {
                                RoundedView{width: Fit height: Fit padding: Inset{top: 2 bottom: 2 left: 6 right: 6}
                                    draw_bg +: {color: violetBg border_radius: 6.0 border_size: 1.0 border_color: violetBd}
                                    View{width: Fit height: Fit flow: Right spacing: 4 align: Align{y: 0.5}
                                        View{width: 10 height: 10 align: Align{x: 0.5 y: 0.5}
                                            spark_icon(violetT, 9)}
                                        Label{text: "AI 摘要生成中…" draw_text.color: violetT draw_text.text_style.font_size: 9}}}
                            } else {
                                if m.labels.len() > 0 { chip(m.labels[0].text, m.labels[0].tone) }
                                if m.labels.len() > 1 { chip(m.labels[1].text, m.labels[1].tone) }
                            }
                            state_pill(m)
                            View{width: Fill height: 1}
                            priority_meter(m)
                        }
                    }
                }
            }
            if sel {
                View{width: Fill height: Fill align: Align{x: 0.0 y: 0.0}
                    View{width: 2 height: Fill align: Align{x: 0.0 y: 0.5}
                        RoundedView{width: 2 height: Fill draw_bg +: {color: violet border_radius: 1.0}}}
                }
            }
        }
    }
}
