fn inbox_screen(){
    // Two independently-scrolling panes on a fixed viewport: the 420px list
    // and the reading column. The list pane paints the page ground as an
    // Overlay underlay so no black shows below shorter content on scroll.
    View{width: Fill height: Fill flow: Right
        View{width: 420 height: Fill flow: Overlay
            RoundedView{width: Fill height: Fill draw_bg +: {color: space border_radius: 0.0}}
            ScrollYView{width: Fill height: Fill flow: Down
            View{width: Fill height: Fit flow: Down spacing: 11 padding: Inset{top: 18 bottom: 14 left: 20 right: 20}
                View{width: Fill height: Fit flow: Right spacing: 10
                    RoundedView{width: 24 height: 24 draw_bg +: {color: violetBg border_radius: 8.0} align: Align{x: 0.5 y: 0.5}
                        View{width: 14 height: 14 align: Align{x: 0.5 y: 0.5}
                            spark_icon(violetT, 13)}}
                    View{width: Fill height: Fit flow: Down spacing: 4
                        Label{width: Fill text: "Vibe Agent 已整理今日 " + cnt("all") + " 封邮件:"
                              draw_text.color: ink66 draw_text.text_style.font_size: 12}
                        View{width: Fill height: Fit flow: Right spacing: 6
                            Label{text: cnt("urgent") + " 封紧急" draw_text.color: redT draw_text.text_style.font_size: 11}
                            Label{text: "· " + cnt("reply") + " 封需回复" draw_text.color: amberT draw_text.text_style.font_size: 11}
                            Label{text: "· " + cnt("later") + " 封可稍后" draw_text.color: ink45 draw_text.text_style.font_size: 11}
                        }
                        Label{width: Fill text: banner_line() draw_text.color: ink45 draw_text.text_style.font_size: 10}
                        if scope_label() != "" {
                            View{width: Fill height: Fit flow: Right spacing: 8 align: Align{y: 0.5} padding: Inset{top: 2}
                                RoundedView{width: Fit height: Fit padding: Inset{top: 2 bottom: 2 left: 8 right: 8}
                                    draw_bg +: {color: violetBg border_radius: 7.0 border_size: 1.0 border_color: violetBd}
                                    Label{text: scope_label() draw_text.color: violetT draw_text.text_style.font_size: 10}}
                                Label{width: Fill text: "再点一次取消 · 或点「收件箱」返回" draw_text.color: ink45 draw_text.text_style.font_size: 9.5}}
                        }
                    }
                }
                View{width: Fill height: Fit flow: Right spacing: 6
                    filter_chip("all", "全部", cnt_chip("all"))
                    filter_chip("urgent", "紧急", cnt_chip("urgent"))
                    filter_chip("reply", "需回复", cnt_chip("reply"))
                    filter_chip("later", "可稍后", cnt_chip("later"))
                }
            }
                RoundedView{width: Fill height: 1 draw_bg +: {color: line border_radius: 0.0}}
            View{width: Fill height: Fit flow: Down
                for i in mails.len() {
                    if pass_scope(i) {
                        if pass_filter(i) { mail_row(i) }
                        RoundedView{width: Fill height: 1 draw_bg +: {color: line border_radius: 0.0}}
                    }
                }
                if cnt_vis() == 0 {
                    View{width: Fill height: Fit flow: Down spacing: 8 padding: Inset{top: 32 bottom: 26 left: 20 right: 20} align: Align{x: 0.5}
                        Label{text: "此视图暂无邮件" draw_text.color: ink draw_text.text_style: theme.font_bold{font_size: 13.5}}
                        Label{width: Fill text: "侧栏邮箱文件夹与 AI 智能分类都是真实筛选;点「收件箱」返回全部邮件。" draw_text.color: ink45 draw_text.text_style.font_size: 11 align: Align{x: 0.5}}
                    }
                }
                View{width: Fill height: 24}
            }
            }
        }
        RoundedView{width: 1 height: Fill draw_bg +: {color: line border_radius: 0.0}}
        // reading column — scrolls itself; content centres at 720 (clamped)
        ScrollYView{width: Fill height: Fill flow: Down
            if selected { reading_pane(current) } else { preview_pane() }
        }
    }
}

