fn tool_btn(icon_key, tint){
    View{width: 32 height: 32 align: Align{x: 0.5 y: 0.5}
        ui_icon(icon_key, tint, 15, space)}
}
fn ghost_btn(color){
    View{width: 32 height: 32 draw_bg +: {color: #x00000000 border_radius: 8.0} align: Align{x: 0.5 y: 0.5}
        more_icon(color, 15)}
}
// list rows for older mails carry the day ("昨天") in `time`; never print it
// twice when the reading stamp combines date + time
fn stamp(m){
    if m.date == "" { return m.time }
    if m.time == m.date { return m.date }
    return m.date + " " + m.time
}
fn brief_status_word(){
    if mails[current].summary_src == "asking" { return "生成中…" }
    if mails[current].summary_src == "ai" { return "模型生成" }
    if mails[current].summary_src == "unavailable" { return "服务不可用" }
    return "练习数据"
}
// inline collapsible AI 速览 — summary / 待办提取 / 语气洞察 in one card,
// right under the sender row (the reference folds the Copilot in here)
fn ai_brief(i){
    let m = mails[i]
    RoundedView{width: Fill height: Fit draw_bg +: {color: violetBg border_radius: 14.0 border_size: 1.0 border_color: violetBd} flow: Down
        // header: brand + collapsed tally + AI 生成 + 0.8s + chevron (no
        // card-level gesture — it would swallow the buttons' hit areas; the
        // practice/AI status word lives on the provenance line instead)
        View{width: Fill height: Fit flow: Right spacing: 8 align: Align{y: 0.5} padding: Inset{top: 14 bottom: 14 left: 18 right: 12}
            View{width: 15 height: 15 align: Align{x: 0.5 y: 0.5}
                spark_icon(violetT, 13)}
            Label{text: "AI 速览 · BRIEF" draw_text.color: violetT draw_text.text_style.font_size: 10}
            if !brief_open {
                Label{text: "" + m.summary.len() + " 项要点 · " + m.actions.len() + " 个待办" draw_text.color: ink45 draw_text.text_style.font_size: 9.5}
            }
            View{width: Fill height: 1}
            ButtonFlat{height: 26 padding: Inset{left: 10 right: 10} text: "AI 生成" on_click: || gen_summary(i)
                draw_bg +: {color: violet color_hover: violet color_down: accB border_radius: 7.0 border_size: 0.0}
                draw_text +: {color: accInk text_style.font_size: 10}}
            Label{text: "0.8s" draw_text.color: ink45 draw_text.text_style.font_size: 10}
            GestureView{width: 28 height: 26 on_tap: |x, y| toggle_brief()
                RoundedView{width: 28 height: 26 draw_bg +: {color: #x00000000 border_radius: 7.0 border_size: 1.0 border_color: violetBd} align: Align{x: 0.5 y: 0.5}
                    chevron_icon(pick(brief_open, 1, 0), violetT, 10)}}
        }
        if brief_open {
            View{width: Fill height: Fit flow: Down spacing: 11 padding: Inset{top: 4 bottom: 18 left: 20 right: 20}
                // summary points
                if m.summary_src == "asking" {
                    Label{width: Fill text: "AI 摘要生成中…" draw_text.color: violetT draw_text.text_style.font_size: 12}
                } else {
                    if m.summary_src == "unavailable" {
                        Label{width: Fill text: "模型服务不可用:" + summary_error + " · 以下为练习数据" draw_text.color: redT draw_text.text_style.font_size: 10}
                    }
                    let pts = m.summary
                    if m.summary_src == "ai" { pts = m.ai_points }
                    for p in pts {
                        View{width: Fill height: Fit flow: Right spacing: 9
                            View{width: 5 height: 5 align: Align{y: 0.5}
                                RoundedView{width: 5 height: 5 draw_bg +: {color: violet border_radius: 3.0}}}
                            Label{width: Fill text: p draw_text.color: inkHi draw_text.text_style.font_size: 12}
                        }
                    }
                }
                // 待办提取
                if m.actions.len() > 0 {
                    RoundedView{width: Fill height: 1 draw_bg +: {color: violetBd border_radius: 0.0}}
                    View{width: Fill height: Fit flow: Right spacing: 7
                        View{width: 13 height: 13 align: Align{x: 0.5 y: 0.5}
                            check_icon(amber, 11)}
                        Label{text: "待办提取" draw_text.color: ink45 draw_text.text_style.font_size: 10}}
                    for a in m.actions {
                        View{width: Fill height: Fit flow: Right spacing: 10 align: Align{y: 0.5}
                            RoundedView{width: 16 height: 16 draw_bg +: {color: pick(a.done, mint, #x00000000) border_radius: 5.0 border_size: 1.0 border_color: pick(a.done, mint, line2)} align: Align{x: 0.5 y: 0.5}
                                if a.done {
                                    View{width: 11 height: 11 align: Align{x: 0.5 y: 0.5}
                                        check_icon(accInk, 9.5)}}
                            }
                            Label{width: Fill text: a.text draw_text.color: pick(a.done, ink38, inkHi) draw_text.text_style.font_size: 12}
                            if a.due != "" {
                                Label{text: "· " + a.due draw_text.color: amberT draw_text.text_style.font_size: 10}}
                        }
                    }
                }
                // 语气洞察
                if m.sent_label != "" {
                    RoundedView{width: Fill height: 1 draw_bg +: {color: violetBd border_radius: 0.0}}
                    View{width: Fill height: Fit flow: Right spacing: 7 align: Align{y: 0.5}
                        View{width: 13 height: 13 align: Align{x: 0.5 y: 0.5}
                            spark_icon(mint, 11)}
                        chip(m.sent_label, m.sent_tone)
                        Label{width: Fill text: m.sent_note draw_text.color: ink66 draw_text.text_style.font_size: 11.5}}
                }
                // provenance line — practice/AI status + the host's model name
                Label{width: Fill text: "由 Vibe Agent 生成 · 0.8s · " + brief_status_word() + pick(m.summary_src == "ai" && ai_model != "", " · " + ai_model, "") draw_text.color: ink45 draw_text.text_style.font_size: 9.5}
            }
        }
    }
}
