// ---- Agent 小队 ------------------------------------------------------------------
fn approve_act(i){ acts[i].handled = true; repaint() }
fn toggle_agent(i){ agents[i].on = !agents[i].on; repaint() }
fn agent_color(k){
    if k == "teal" { return cyan }
    if k == "ok" { return mint }
    if k == "amber" { return amber }
    return violet
}
fn agent_soft(k){
    if k == "teal" { return cyanBg }
    if k == "ok" { return mintBg }
    if k == "amber" { return amberBg }
    return violetBg
}
fn running_cnt(){
    let n = 0
    for i in agents.len() { if agents[i].on { n = n + 1 } }
    return n
}
fn pending_cnt(){
    let n = 0
    for i in acts.len() {
        if acts[i].status == "approval" { if !acts[i].handled { n = n + 1 } }
    }
    return n
}
fn stat_cell(icon_key, label, value, color){
    RoundedView{width: Fill height: Fit padding: Inset{top: 18 bottom: 18 left: 18 right: 18}
        draw_bg +: {color: panel2 border_radius: 14.0 border_size: 1.0 border_color: line} flow: Down spacing: 11
        View{width: Fill height: Fit flow: Right spacing: 6 align: Align{y: 0.5}
            View{width: 13 height: 13 align: Align{x: 0.5 y: 0.5}
                ui_icon(icon_key, color, 11, panel2)}
            Label{text: label draw_text.color: ink45 draw_text.text_style.font_size: 9.5}}
        Label{text: value draw_text.color: color draw_text.text_style: theme.font_bold{font_size: 28}}
    }
}
fn agent_card(i){
    let a = agents[i]
    RoundedView{width: Fill height: Fit padding: Inset{top: 18 bottom: 16 left: 18 right: 18}
        draw_bg +: {color: panel2 border_radius: 16.0 border_size: 1.0 border_color: line} flow: Down spacing: 11
            View{width: Fill height: Fit flow: Right spacing: 10
            RoundedView{width: 40 height: 40
                draw_bg +: {color: agent_soft(a.color) border_radius: 12.0 border_size: 1.0 border_color: agent_color(a.color)} align: Align{x: 0.5 y: 0.5}
                View{width: 22 height: 22 align: Align{x: 0.5 y: 0.5}
                    ui_icon(a.icon, agent_color(a.color), 19, agent_soft(a.color))}}
            View{width: Fill height: Fit flow: Down spacing: 3
                View{width: Fill height: Fit flow: Right spacing: 6 align: Align{y: 0.5}
                    Label{text: a.name draw_text.color: ink draw_text.text_style: theme.font_bold{font_size: 13.5}}
                    if a.on {
                        live_dot()
                    }
                    Label{text: a.status draw_text.color: pick(a.on, mint, amber) draw_text.text_style.font_size: 9.5}}}
            View{width: 1 height: Fill}
            GestureView{width: 32 height: 18 on_tap: |x, y| toggle_agent(i)
                RoundedView{width: 32 height: 18 draw_bg +: {color: pick(a.on, violet, line2) border_radius: 9.0} flow: Overlay
                    View{width: 32 height: 18 align: pick(a.on, Align{x: 1.0 y: 0.5}, Align{x: 0.0 y: 0.5})
                        View{width: 18 height: 18 align: Align{x: 0.5 y: 0.5}
                            RoundedView{width: 14 height: 14 draw_bg +: {color: panel border_radius: 7.0}}}
                    }
                }
            }
        }
        Label{width: Fill text: a.desc draw_text.color: ink66 draw_text.text_style.font_size: 11.5}
        RoundedView{width: Fill height: 1 draw_bg +: {color: line border_radius: 0.0}}
        // stat + today stack vertically: side by side they squeeze the Fill
        // stat label out of the tree on 157px cards (1000px window)
        View{width: Fill height: Fit flow: Down spacing: 3
            Label{width: Fill text: a.stat draw_text.color: ink45 draw_text.text_style.font_size: 10}
            Label{width: Fill text: a.today draw_text.color: agent_color(a.color) draw_text.text_style.font_size: 10}}
    }
}
fn act_row(i){
    let a = acts[i]
    View{width: Fill height: Fit flow: Down padding: Inset{top: 14 bottom: 14 left: 16 right: 16} spacing: 7
        View{width: Fill height: Fit flow: Right spacing: 8 align: Align{y: 0.5}
            Label{text: a.time draw_text.color: ink45 draw_text.text_style.font_size: 10}
            Label{text: a.agent draw_text.color: violetT draw_text.text_style.font_size: 10}
            View{width: Fill height: 1}
            if a.status == "running" {
                RoundedView{width: Fit height: Fit padding: Inset{top: 2 bottom: 2 left: 6 right: 6}
                    draw_bg +: {color: cyanBg border_radius: 6.0 border_size: 1.0 border_color: cyanBd}
                    Label{text: "RUNNING" draw_text.color: cyanT draw_text.text_style.font_size: 9}}
            } else {
                if a.status == "done" {
                    View{width: Fit height: Fit flow: Right spacing: 4 align: Align{y: 0.5}
                        View{width: 11 height: 11 align: Align{x: 0.5 y: 0.5}
                            check_icon(mint, 9.5)}
                        Label{text: "DONE" draw_text.color: mint draw_text.text_style.font_size: 9.5}}
                } else {
                    if a.handled {
                        Label{text: "已处理" draw_text.color: ink38 draw_text.text_style.font_size: 9.5}
                    } else {
                        Label{text: "需审批" draw_text.color: amberT draw_text.text_style.font_size: 9.5}
                    }
                }
            }
        }
        Label{width: Fill text: a.text draw_text.color: inkHi draw_text.text_style.font_size: 12}
        if a.status == "approval" {
            if !a.handled {
                View{width: Fill height: Fit flow: Right spacing: 8
                    ButtonFlat{height: 28 text: "批准" on_click: || approve_act(i)
                        draw_bg +: {color: mintBg color_hover: mintBd color_down: mintBg border_radius: 7.0 border_size: 1.0 border_color: mintBd}
                        draw_text +: {color: mintT text_style.font_size: 10.5}}
                    ButtonFlat{height: 28 text: "忽略" on_click: || approve_act(i)
                        draw_bg +: {color: #x00000000 color_hover: redBg color_down: redBg border_radius: 7.0 border_size: 1.0 border_color: line2}
                        draw_text +: {color: ink55 text_style.font_size: 10.5}}
                }
            }
        }
    }
}
fn agents_screen(){
    ScrollYView{width: Fill height: Fill flow: Down
    // content column — Fill width (a fixed 1180 column's children lay out at
    // 1180 even when the column clamps, pushing the activity feed's badges
    // and approval buttons past the window edge — probed)
    View{width: Fill height: Fit flow: Down padding: Inset{top: 24 bottom: 32 left: 28 right: 26} spacing: 18
            View{width: Fill height: Fit flow: Right spacing: 14
                stat_cell("spark", "运行中的 AGENT", "" + running_cnt(), violet)
