                        Label{text: "SQUAD · 4 UNITS" draw_text.color: ink45 draw_text.text_style.font_size: 9.5}}
                    View{width: Fill height: Fit flow: Right spacing: 14
                        agent_card(0)
                        agent_card(1)
                    }
                    View{width: Fill height: Fit flow: Right spacing: 14
