                    }
                    RoundedView{width: Fill height: Fit padding: Inset{top: 16 bottom: 16 left: 18 right: 18}
                        draw_bg +: {color: panel2 border_radius: 16.0 border_size: 1.0 border_color: line} flow: Down spacing: 12
                        View{width: Fill height: Fit flow: Right spacing: 8 align: Align{y: 0.5}
                            Label{text: "自动化程度" draw_text.color: ink45 draw_text.text_style.font_size: 10}
                            View{width: Fill height: 1}
                            Label{text: "SEMI-AUTO" draw_text.color: violetT draw_text.text_style.font_size: 10}}
                        RoundedView{width: Fill height: 4 draw_bg +: {color: line border_radius: 2.0} flow: Overlay
                            RoundedView{width: 197 height: 4 draw_bg +: {color: violet border_radius: 2.0}}
                            View{width: 210 height: 4 align: Align{x: 0.0 y: 0.5}
