                                Label{text: "全自动" draw_text.color: ink45 draw_text.text_style.font_size: 9.5}}
                            Label{width: Fill text: "半自动 · 关键动作需审批" draw_text.color: violetT draw_text.text_style.font_size: 9.5 align: Align{x: 0.5}}}
                    }
                }
                View{width: 340 height: Fit flow: Down spacing: 12
                    View{width: Fill height: Fit flow: Right spacing: 8 align: Align{y: 0.5}
