// 通知中心:需要你处理的事,点条目直达
fn bell_panel(){
    View{width: Fill height: Fill align: Align{x: 1.0 y: 0.0}
        View{width: 332 height: Fit padding: Inset{top: 10 right: 12}
            RoundedView{width: Fill height: Fit draw_bg +: {color: panel border_radius: 14.0 border_size: 1.0 border_color: line2} flow: Down
                View{width: Fill height: Fit flow: Right spacing: 8 align: Align{y: 0.5} padding: Inset{top: 14 bottom: 12 left: 16 right: 14}
                    panel_lead("dot", violetT, panel)
                    Label{text: "通知 · NOTIFICATIONS" draw_text.color: ink draw_text.text_style: theme.font_bold{font_size: 12.5}}
                    View{width: Fill height: 1}
                    if notify_cnt() > 0 {
                        RoundedView{width: Fit height: Fit padding: Inset{top: 2 bottom: 2 left: 8 right: 8}
                            draw_bg +: {color: redBg border_radius: 8.0 border_size: 1.0 border_color: redBd}
                            Label{text: "" + notify_cnt() draw_text.color: redT draw_text.text_style.font_size: 10}}
                    }
                }
                RoundedView{width: Fill height: 1 draw_bg +: {color: line border_radius: 0.0}}
                if pending_cnt() > 0 {
                    GestureView{width: Fill height: Fit on_tap: |x, y| bell_agents()
                        View{width: Fill height: Fit flow: Right spacing: 10 align: Align{y: 0.5} padding: Inset{top: 12 bottom: 12 left: 16 right: 14}
                            panel_lead("check", amber, panel)
                            View{width: Fill height: Fit flow: Down spacing: 2
                                Label{width: Fill text: "" + pending_cnt() + " 项 Agent 活动待审批" draw_text.color: ink draw_text.text_style.font_size: 12.5}
                                Label{width: Fill text: "批准后才会执行" draw_text.color: ink45 draw_text.text_style.font_size: 10}}
                            panel_arrow(violetT)}}
                    RoundedView{width: Fill height: 1 draw_bg +: {color: line border_radius: 0.0}}
                }
                if failed_cnt() > 0 {
                    GestureView{width: Fill height: Fit on_tap: |x, y| bell_failed()
                        View{width: Fill height: Fit flow: Right spacing: 10 align: Align{y: 0.5} padding: Inset{top: 12 bottom: 12 left: 16 right: 14}
                            panel_lead("x", redT, panel)
                            View{width: Fill height: Fit flow: Down spacing: 2
                                Label{width: Fill text: "" + failed_cnt() + " 封发送失败待重试" draw_text.color: ink draw_text.text_style.font_size: 12.5}
                                Label{width: Fill text: "草稿已保留,可重试" draw_text.color: ink45 draw_text.text_style.font_size: 10}}
                            panel_arrow(violetT)}}
                    RoundedView{width: Fill height: 1 draw_bg +: {color: line border_radius: 0.0}}
                }
                if cntf("drafts") > 0 {
                    GestureView{width: Fill height: Fit on_tap: |x, y| bell_drafts()
                        View{width: Fill height: Fit flow: Right spacing: 10 align: Align{y: 0.5} padding: Inset{top: 12 bottom: 12 left: 16 right: 14}
                            panel_lead("doc", violetT, panel)
                            View{width: Fill height: Fit flow: Down spacing: 2
                                Label{width: Fill text: "" + cntf("drafts") + " 份回复草稿待发送" draw_text.color: ink draw_text.text_style.font_size: 12.5}
                                Label{width: Fill text: "两步确认后才会发出" draw_text.color: ink45 draw_text.text_style.font_size: 10}}
                            panel_arrow(violetT)}}
                    RoundedView{width: Fill height: 1 draw_bg +: {color: line border_radius: 0.0}}
                }
                if urgent_unread_cnt() > 0 {
                    GestureView{width: Fill height: Fit on_tap: |x, y| bell_urgent()
                        View{width: Fill height: Fit flow: Right spacing: 10 align: Align{y: 0.5} padding: Inset{top: 12 bottom: 12 left: 16 right: 14}
                            panel_lead("spark", redT, panel)
                            View{width: Fill height: Fit flow: Down spacing: 2
                                Label{width: Fill text: "" + urgent_unread_cnt() + " 封紧急邮件未读" draw_text.color: ink draw_text.text_style.font_size: 12.5}
                                Label{width: Fill text: "AI 标记为今日优先处理" draw_text.color: ink45 draw_text.text_style.font_size: 10}}
                            panel_arrow(violetT)}}
                    RoundedView{width: Fill height: 1 draw_bg +: {color: line border_radius: 0.0}}
                }
                if notify_cnt() == 0 {
                    if cntf("drafts") == 0 {
                        if urgent_unread_cnt() == 0 {
                            View{width: Fill height: Fit flow: Down spacing: 3 padding: Inset{top: 14 bottom: 14 left: 16 right: 14}
                                Label{width: Fill text: "一切就绪 · 暂无需要你处理的事" draw_text.color: ink66 draw_text.text_style.font_size: 12}
                                Label{width: Fill text: "Vibe Agent 在后台继续整理你的收件箱" draw_text.color: ink45 draw_text.text_style.font_size: 10}}
                        }
                    }
                }
                View{width: Fill height: Fit padding: Inset{top: 9 bottom: 10 left: 16 right: 14}
                    Label{width: Fill text: "点条目直达 · 点空白处关闭" draw_text.color: ink38 draw_text.text_style.font_size: 9.5}}
            }
        }
    }
}

