                    View{width: Fill height: 1}
                    Label{text: "" + meeting_cnt() + " 场" draw_text.color: cyanT draw_text.text_style.font_size: 10}
                }
                RoundedView{width: Fill height: 1 draw_bg +: {color: line border_radius: 0.0}}
                for i in mails.len() {
                    if mails[i].meeting_title != "" {
                        GestureView{width: Fill height: Fit on_tap: |x, y| open_meeting(i)
                            View{width: Fill height: Fit flow: Right spacing: 10 align: Align{y: 0.5} padding: Inset{top: 12 bottom: 12 left: 16 right: 14}
                                panel_lead("dot", cyanT, panel)
                                View{width: Fill height: Fit flow: Down spacing: 3
                                    Label{width: Fill text: mails[i].meeting_title draw_text.color: ink draw_text.text_style.font_size: 12.5}
                                    View{width: Fill height: Fit flow: Right spacing: 10
                                        Label{text: mails[i].meeting_time draw_text.color: ink66 draw_text.text_style.font_size: 10.5}
                                        View{width: Fit height: Fit flow: Right spacing: 4 align: Align{y: 0.5}
                                            View{width: 11 height: 11 align: Align{x: 0.5 y: 0.5}
                                                dot_ring_icon(ink45, 8.5)}
                                            Label{text: mails[i].meeting_loc draw_text.color: ink45 draw_text.text_style.font_size: 10.5}}}
                                }
                                panel_arrow(violetT)}}
                        RoundedView{width: Fill height: 1 draw_bg +: {color: line border_radius: 0.0}}
                    }
                }
                if meeting_cnt() == 0 {
                    View{width: Fill height: Fit flow: Down spacing: 3 padding: Inset{top: 14 bottom: 14 left: 16 right: 14}
                        Label{width: Fill text: "暂无邮件中识别到的会议" draw_text.color: ink66 draw_text.text_style.font_size: 12}
                        Label{width: Fill text: "收到含时间地点的邮件后会自动出现" draw_text.color: ink45 draw_text.text_style.font_size: 10}}
                }
                View{width: Fill height: Fit padding: Inset{top: 9 bottom: 10 left: 16 right: 14}
                    Label{width: Fill text: "会议由 AI 从邮件提取 · 点击打开原邮件" draw_text.color: ink38 draw_text.text_style.font_size: 9.5}}
            }
        }
    }
}

// 设置:主题、练习开关与数据口径
fn theme_mode_chip(mode, label){
    let act = themeMode == mode
    ButtonFlat{height: 26 padding: Inset{left: 10 right: 10} text: label on_click: || apply_theme_mode(mode)
        draw_bg +: {color: pick(act, violetBg, #x00000000) color_hover: violetBg color_down: violetBg border_radius: 8.0 border_size: 1.0 border_color: pick(act, violetBd, line2)}
        draw_text +: {color: pick(act, violetT, ink66) text_style.font_size: 10.5}}
}
fn set_panel(){
    View{width: Fill height: Fill align: Align{x: 0.0 y: 1.0}
        View{width: 332 height: Fit padding: Inset{left: 12 bottom: 12}
            RoundedView{width: Fill height: Fit draw_bg +: {color: panel border_radius: 14.0 border_size: 1.0 border_color: line2} flow: Down
                View{width: Fill height: Fit flow: Right spacing: 8 align: Align{y: 0.5} padding: Inset{top: 14 bottom: 12 left: 16 right: 14}
                    View{width: 14 height: 14 align: Align{x: 0.5 y: 0.5}
                        sliders_icon(ink45, 14)}
                    Label{text: "设置 · SETTINGS" draw_text.color: ink draw_text.text_style: theme.font_bold{font_size: 12.5}}
                    View{width: Fill height: 1}
                }
                RoundedView{width: Fill height: 1 draw_bg +: {color: line border_radius: 0.0}}
                // 邮箱账号 — connect / refresh / disconnect, all through the
                // host service (credentials never enter the app)
                View{width: Fill height: Fit flow: Down spacing: 8 padding: Inset{top: 12 bottom: 12 left: 16 right: 14}
                    View{width: Fill height: Fit flow: Right spacing: 8 align: Align{y: 0.5}
                        panel_lead("mail", violetT, panel)
                        Label{width: Fill text: "邮箱账号" draw_text.color: ink draw_text.text_style.font_size: 12.5}
                        if mail_link == "live" {
                            Label{text: "已连接" draw_text.color: mintT draw_text.text_style.font_size: 10.5}
                        } else {
                            if mail_link == "no_account" {
                                Label{text: "未添加" draw_text.color: amberT draw_text.text_style.font_size: 10.5}
                            } else {
                                Label{text: "不可用" draw_text.color: ink45 draw_text.text_style.font_size: 10.5}
                            }
                        }
                    }
                    if mail_link == "live" {
                        Label{width: Fill text: account_addr draw_text.color: ink66 draw_text.text_style.font_size: 10.5}
                    }
                    if mail_link == "no_account" {
                        Label{width: Fill text: "在宿主自己的登录面板中添加,凭据只存宿主侧。" draw_text.color: ink45 draw_text.text_style.font_size: 10}
                    }
                    View{width: Fill height: Fit flow: Right spacing: 8
                        if mail_link == "no_account" {
                            ButtonFlat{height: 28 padding: Inset{left: 10 right: 10} text: "添加账号" on_click: || mail_add_account()
                                draw_bg +: {color: violet color_hover: violet color_down: accB border_radius: 8.0 border_size: 0.0}
                                draw_text +: {color: accInk text_style.font_size: 10.5}}
                        } else {
                            if mail_link == "live" {
                                ButtonFlat{height: 28 padding: Inset{left: 10 right: 10} text: "刷新" on_click: || mail_refresh()
                                    draw_bg +: {color: #x00000000 color_hover: white7 color_down: white7 border_radius: 8.0 border_size: 1.0 border_color: line2}
                                    draw_text +: {color: ink66 text_style.font_size: 10.5}}
                                ButtonFlat{height: 28 padding: Inset{left: 10 right: 10} text: pick(mail_arm, "确认断开?", "断开") on_click: || mail_disconnect()
                                    draw_bg +: {color: pick(mail_arm, redBg, #x00000000) color_hover: redBg color_down: redBg border_radius: 8.0 border_size: 1.0 border_color: pick(mail_arm, redBd, line2)}
                                    draw_text +: {color: pick(mail_arm, redT, ink66) text_style.font_size: 10.5}}
                            } else {
                                ButtonFlat{height: 28 padding: Inset{left: 10 right: 10} text: "重试连接" on_click: || mail_refresh()
                                    draw_bg +: {color: #x00000000 color_hover: white7 color_down: white7 border_radius: 8.0 border_size: 1.0 border_color: line2}
                                    draw_text +: {color: ink66 text_style.font_size: 10.5}}
                            }
                        }
                    }
                }
                RoundedView{width: Fill height: 1 draw_bg +: {color: line border_radius: 0.0}}
                // 主题 — three modes: follow the host's light/dark, or pin
                // light / dark. The choice persists (theme.json) and the
                // poller follows Shell appearance changes in system mode.
                View{width: Fill height: Fit flow: Down spacing: 8 padding: Inset{top: 12 bottom: 12 left: 16 right: 14}
                    View{width: Fill height: Fit flow: Right spacing: 10 align: Align{y: 0.5}
                        View{width: 14 height: 14 align: Align{x: 0.5 y: 0.5}
                            if themeLight {
                                sun_icon(ink45, 14)
                            } else {
                                moon_icon(ink45, 14, panel)
                            }}
                        Label{width: Fill text: "主题" draw_text.color: ink draw_text.text_style.font_size: 12.5}
                        if themeMode == "system" {
                            if system_prefers_dark() == nil {
                                Label{text: "系统未知" draw_text.color: ink45 draw_text.text_style.font_size: 10}
                            } else {
                                Label{text: "跟随系统" draw_text.color: violetT draw_text.text_style.font_size: 10}
                            }
                        }
                    }
                    View{width: Fill height: Fit flow: Right spacing: 6
                        theme_mode_chip("system", "跟随系统")
                        theme_mode_chip("light", "亮色")
                        theme_mode_chip("dark", "暗色")
                    }
                }
                RoundedView{width: Fill height: 1 draw_bg +: {color: line border_radius: 0.0}}
                View{width: Fill height: Fit flow: Right spacing: 10 align: Align{y: 0.5} padding: Inset{top: 12 bottom: 12 left: 16 right: 14}
                    panel_lead("x", redT, panel)
                    Label{width: Fill text: "练习:模拟服务中断" draw_text.color: ink draw_text.text_style.font_size: 12.5}
                    ButtonFlat{height: 26 padding: Inset{left: 10 right: 10} text: pick(simulate_outage, "已开启", "已关闭") on_click: || toggle_outage()
                        draw_bg +: {color: pick(simulate_outage, redBg, panel2) color_hover: white7 color_down: white7 border_radius: 8.0 border_size: 1.0 border_color: pick(simulate_outage, redBd, line2)}
                        draw_text +: {color: pick(simulate_outage, redT, ink66) text_style.font_size: 10.5}}
                }
                RoundedView{width: Fill height: 1 draw_bg +: {color: line border_radius: 0.0}}
                View{width: Fill height: Fit flow: Down spacing: 6 padding: Inset{top: 12 bottom: 8 left: 16 right: 14}
                    Label{text: "练习数据口径" draw_text.color: ink45 draw_text.text_style.font_size: 9.5}
                    Label{width: Fill text: "邮件与 Agent 小队为练习数据;真实收发经平台 mail 宿主服务,凭据只存宿主侧;AI 摘要与起草为 model 服务一次性调用,密钥不经应用。" draw_text.color: ink66 draw_text.text_style.font_size: 10}
                }
                View{width: Fill height: Fit padding: Inset{top: 8 bottom: 10 left: 16 right: 14}
                    Label{width: Fill text: "VibeMail 0.6.17 · vibemail" draw_text.color: ink38 draw_text.text_style.font_size: 9.5}}
            }
        }
    }
}

// ---- root ---------------------------------------------------------------------
// No separate ground root: on_render-minted layers composite in a late extra
// pass regardless of tree order (probed), so an underlay root leaks ABOVE the
// UI. The page bg is therefore the FIRST item minted inside body's own
// on_render — under every screen, repainted on theme switches.
SolidView{width: Fill height: Fill flow: Overlay draw_bg.color: #xf3f1e6
    View{width: Fill height: Fill flow: Right
        sidec := View{width: Fit height: Fill flow: Right on_render: || {
            sidebar()
            RoundedView{width: 1 height: Fill draw_bg +: {color: sepC border_radius: 0.0}}
        }}
        View{width: Fill height: Fill flow: Down
            barc := View{width: Fill height: Fit flow: Down on_render: || {
                top_bar()
                RoundedView{width: Fill height: 1 draw_bg +: {color: sepC border_radius: 0.0}}
            }}
            // body is a FIXED viewport area; each pane scrolls itself (the
            // web design's overflow-y-auto columns) — one page scroll made
            // the columns push each other around. The page ground is the
            // first Overlay child here, under every screen.
            body := View{width: Fill height: Fill flow: Overlay on_render: || {
                RoundedView{width: Fill height: Fill draw_bg +: {color: space border_radius: 0.0}}
                if screen == "inbox" { inbox_screen() }
                if screen == "write" { write_screen() }
                if screen == "agents" { agents_screen() }
                // popover panels + their dim veil, minted LAST so they sit
                // above every screen; the veil itself closes on tap
                if pop != "" {
                    GestureView{width: Fill height: Fill on_tap: |x, y| open_pop("")
                        RoundedView{width: Fill height: Fill draw_bg +: {color: white7 border_radius: 0.0}}}
                    if pop == "bell" { bell_panel() }
                    if pop == "cal" { cal_panel() }
                    if pop == "set" { set_panel() }
                }
            }}
        }
    }
}
